fn reverse(a: &Vec<char>) -> Vec<char> {
    // .iter()   — iterate over &char
    // .copied() — map &char → char (char is Copy)
    // .rev()    — reverse the iteration order
    // .collect()— gather into a Vec<char>
    a.iter().copied().rev().collect()
}

fn main() {
    let v = vec!['h', 'e', 'l', 'l', 'o'];
    let r = reverse(&v);
    assert_eq!(r, vec!['o', 'l', 'l', 'e', 'h']);
    println!("{:?} reversed is {:?}", v, r);
}